var n=`0481-kafta`;var o=`world-0481`;var r=`LB`;var a=`western-asia`;var l=4;var t=34;var s={en:`Kafta`,ua:`Кафта`};var d={en:`A traditional dish from Lebanon, centered on ground lamb, yellow onion, parsley. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ліван. Основні складники: фарш з ягнятини, жовта цибуля, петрушка. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`ground-lamb`,540,`g`],[`yellow-onion`,190,`g`],[`parsley`,60,`g`],[`allspice-berries`,4,`g`],[`ground-cumin`,5,`g`]]},{en:`Shape minced lamb around broad skewers in long even logs; refrigerate briefly if needed to hold their shape.`,ua:`Зліпіть із баранячого фаршу рівні довгі ковбаски навколо широких шампурів; за потреби трохи охолодіть для стабільної форми.`,t:[`threading-skewers`],m:9,i:[]},{en:`Grill over medium-high heat for about 15 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 15 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:15,i:[[`extra-virgin-olive-oil`,35,`ml`]]}];var u={slug:n,id:o,country:`LB`,region:a,servings:4,minutes:34,title:s,text:d,steps:g};export{r as country,u as default,o as id,t as minutes,a as region,l as servings,n as slug,g as steps,d as text,s as title};